from datetime import datetime

def format_unified_response(agent_response: str, routing_info: dict) -> str:
    """Format unified response with routing metadata"""
    agent = routing_info.get('agent', 'unknown')
    confidence = routing_info.get('confidence', 'unknown')

    agent_name = 'VAR-Lens' if agent == 'var_lens' else 'Tactical Pulse'

    response = f"""╔══════════════════════════════════════════════════════════╗
║              FanPulse AI Assistant Response              ║
╚══════════════════════════════════════════════════════════╝

🤖 Agent: {agent_name}
📊 Routing Confidence: {confidence}
⏰ Timestamp: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}

{'─' * 60}

{agent_response}

{'─' * 60}

💡 Powered by IBM Granite 4.1 8B
📚 Data Sources: FIFA Documents + 49K+ Historical Matches
"""
    return response
